async (cursor, num, params) => {
  if (location.hostname !== 'www.photopea.com') throw new Error('[photopea-place] 这张标签没连上 photopea.com（现在是 ' + location.href.slice(0, 60) + '，多半是连接被掐断）：去那张标签按一次刷新，别关它');
  if (window._cf_chl_opt || /请稍候|Just a moment|安全验证/.test(document.title + ' ' + (document.body ? document.body.innerText.slice(0, 200) : ''))) throw new Error('[photopea-place] Photopea 标签停在 Cloudflare 真人验证页：去那张「Photopea API」标签点一下验证（只需一次，标签常驻不关），再跑');
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const pageStart = Date.now();
  const W = Number(params.width), H = Number(params.height);
  if (!(W > 0 && H > 0)) throw new Error('[photopea-place] width/height 必须是正整数');
  const images = String(params.images || '').split('\n').filter(Boolean);
  let layers; try { layers = JSON.parse(params.layers); } catch (e) { throw new Error('[photopea-place] layers 不是合法 JSON: ' + e.message); }
  if (!Array.isArray(layers) || !layers.length) throw new Error('[photopea-place] layers 要是非空数组');
  const format = String(params.format || 'png');
  // —— Photopea 宿主：同源 iframe（photopea.com 顶层不听 postMessage，嵌成 iframe 才听）——
  const ensureFrame = async () => {
    let f = document.getElementById('pp');
    if (f) { // 上一轮留下的热 iframe：应一声就复用，不应就换新的
      const alive = await new Promise(res => { const h = e => { if (e.source === f.contentWindow && e.data === 'pong') { window.removeEventListener('message', h); res(true); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); res(false); }, 4000); f.contentWindow.postMessage('app.echoToOE("pong");', '*'); });
      if (alive) return f;
      f.remove();
    }
    f = document.createElement('iframe'); f.id = 'pp'; f.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;border:0;background:#fff;z-index:2147483647';
    const ready = new Promise((res, rej) => { const h = e => { if (e.source === f.contentWindow && e.data === 'done') { window.removeEventListener('message', h); res(); } }; window.addEventListener('message', h); setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-place] Photopea iframe 25s 没就绪')); }, 25000); });
    f.src = 'https://www.photopea.com/#' + encodeURIComponent(JSON.stringify({ environment: {} }));
    document.body.appendChild(f);
    await ready;
    return f;
  };
  const f = await ensureFrame();
  // 跑一段 Photopea 脚本，等它最后一句 echo 的标记；二进制（saveToOE）顺手收下
  const pp = (script, ms) => new Promise((res, rej) => {
    const mark = 'ok#' + Math.random().toString(36).slice(2, 8); let bin = null; const got = [];
    const h = e => { if (e.source !== f.contentWindow) return; if (e.data instanceof ArrayBuffer) { bin = e.data; return; } if (typeof e.data !== 'string') return; got.push(e.data); if (e.data === mark) { window.removeEventListener('message', h); clearTimeout(t); res({ bin, got }); } };
    const t = setTimeout(() => { window.removeEventListener('message', h); rej(new Error('[photopea-place] Photopea 脚本 ' + ms + 'ms 内没跑完（脚本出错时 Photopea 不报错、只是没有回音）: ' + script.slice(0, 120) + ' | 收到: ' + got.join('/'))); }, ms);
    window.addEventListener('message', h);
    f.contentWindow.postMessage(script + '\napp.echoToOE(' + JSON.stringify(mark) + ');', '*');
  });
  let B = 0; // 清完临时文档后已有的文档数（用户自己开着的）；本轮的文档从 app.documents[B] 起
  const probe = async () => (await pp('app.echoToOE("docs=" + app.documents.length + " w=" + (app.documents.length ? app.activeDocument.width : 0));', 5000)).got.find(s => s.startsWith('docs='));
  const waitDocs = async (n, w, ms) => { const t0 = Date.now(); for (;;) { const s = await probe(); if (s === 'docs=' + (B + n) + ' w=' + w) return; if (Date.now() - t0 > ms) throw new Error('[photopea-place] 等文档就绪超时，现在 ' + s + '，要 docs=' + n + ' w=' + w); await sleep(300); } };
  // —— 几何：单应（4 点→4 点），逆向映射 + 双线性采样（预乘 alpha，边缘不发黑）——
  const solveH = (s, d) => { // 求 3x3 H 使 H·s_i ~ d_i；8 未知数高斯消元
    const A = [], b = [];
    for (let i = 0; i < 4; i++) { const [x, y] = s[i], [u, v] = d[i]; A.push([x, y, 1, 0, 0, 0, -u * x, -u * y]); b.push(u); A.push([0, 0, 0, x, y, 1, -v * x, -v * y]); b.push(v); }
    const n = 8; for (let c = 0; c < n; c++) { let p = c; for (let r = c + 1; r < n; r++) if (Math.abs(A[r][c]) > Math.abs(A[p][c])) p = r; [A[c], A[p]] = [A[p], A[c]]; [b[c], b[p]] = [b[p], b[c]]; for (let r = 0; r < n; r++) { if (r === c) continue; const k = A[r][c] / A[c][c]; for (let j = c; j < n; j++) A[r][j] -= k * A[c][j]; b[r] -= k * b[c]; } }
    const h = b.map((v, i) => v / A[i][i]); return [h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7], 1];
  };
  const loadImg = src => new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = () => rej(new Error('[photopea-place] 图片加载失败')); im.src = src; });
  const warpLayer = async (lay) => {
    const src = images[Number(lay.image) || 0]; if (!src) throw new Error('[photopea-place] layers[].image 指到不存在的 images 序号');
    const im = await loadImg(src); const sw = im.naturalWidth, sh = im.naturalHeight;
    const sc = document.createElement('canvas'); sc.width = sw; sc.height = sh; const sctx = sc.getContext('2d'); sctx.drawImage(im, 0, 0);
    const S = sctx.getImageData(0, 0, sw, sh).data;
    const dst = lay.quad ? lay.quad : (lay.rect ? [[lay.rect[0], lay.rect[1]], [lay.rect[0] + lay.rect[2], lay.rect[1]], [lay.rect[0] + lay.rect[2], lay.rect[1] + lay.rect[3]], [lay.rect[0], lay.rect[1] + lay.rect[3]]] : null);
    if (!dst) throw new Error('[photopea-place] 每层要有 quad（四角）或 rect（[x,y,w,h]）');
    const srcQ = lay.src || [[0, 0], [sw, 0], [sw, sh], [0, sh]];
    const Hinv = solveH(dst, srcQ); // 目标像素 → 源像素
    const oc = document.createElement('canvas'); oc.width = W; oc.height = H; const octx = oc.getContext('2d');
    const x0 = Math.max(0, Math.floor(Math.min(...dst.map(p => p[0])))), x1 = Math.min(W, Math.ceil(Math.max(...dst.map(p => p[0]))));
    const y0 = Math.max(0, Math.floor(Math.min(...dst.map(p => p[1])))), y1 = Math.min(H, Math.ceil(Math.max(...dst.map(p => p[1]))));
    const bw = x1 - x0, bh = y1 - y0; if (bw <= 0 || bh <= 0) throw new Error('[photopea-place] 目标四角完全在画幅外');
    const out = octx.createImageData(bw, bh), O = out.data;
    // 目标四角内才画（凸四边形：点在每条边同侧）
    const inside = (x, y) => { let sgn = 0; for (let i = 0; i < 4; i++) { const [ax, ay] = dst[i], [bx, by] = dst[(i + 1) % 4]; const cr = (bx - ax) * (y - ay) - (by - ay) * (x - ax); if (cr !== 0) { if (sgn === 0) sgn = Math.sign(cr); else if (Math.sign(cr) !== sgn) return false; } } return true; };
    for (let y = y0; y < y1; y++) for (let x = x0; x < x1; x++) {
      const px = x + 0.5, py = y + 0.5; if (!inside(px, py)) continue;
      const den = Hinv[6] * px + Hinv[7] * py + 1; const u = (Hinv[0] * px + Hinv[1] * py + Hinv[2]) / den - 0.5, v = (Hinv[3] * px + Hinv[4] * py + Hinv[5]) / den - 0.5;
      const ux = Math.floor(u), vy = Math.floor(v); const fx = u - ux, fy = v - vy;
      let r = 0, g = 0, b = 0, a = 0;
      for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) { const sx = ux + dx, sy = vy + dy; if (sx < 0 || sy < 0 || sx >= sw || sy >= sh) continue; const wgt = (dx ? fx : 1 - fx) * (dy ? fy : 1 - fy); const i = (sy * sw + sx) * 4; const al = S[i + 3] * wgt; r += S[i] * al; g += S[i + 1] * al; b += S[i + 2] * al; a += al; }
      if (a <= 0) continue; const o = ((y - y0) * bw + (x - x0)) * 4; O[o] = r / a; O[o + 1] = g / a; O[o + 2] = b / a; O[o + 3] = a;
    }
    octx.putImageData(out, x0, y0);
    return oc.toDataURL('image/png');
  };
  // —— 组装：新建透明画布 → 每层各开成文档、复制进画布（位置照搬，warp 已把它画在画幅坐标里）→ 导出 ——
  await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '清掉上轮残留的临时文档');
  B = Number(((await probe()) || 'docs=0').slice(5).split(' ')[0]) || 0;
  await pp('app.documents.add(' + W + ', ' + H + ', 72, "~stream~scene", NewDocumentMode.RGB, DocumentFill.TRANSPARENT);', 8000);
  await waitDocs(1, W, 8000);
  for (let i = 0; i < layers.length; i++) {
    const url = await warpLayer(layers[i]);
    await pp('app.open(' + JSON.stringify(url) + ');', 20000);
    await waitDocs(2, W, 20000);
    await pp('var src = app.activeDocument; src.layers[0].duplicate(app.documents[' + B + '], ElementPlacement.PLACEATBEGINNING); src.close(); app.activeDocument = app.documents[' + B + ']; app.activeDocument.layers[0].name = ' + JSON.stringify(String(layers[i].name || ('layer' + i))) + ';', 8000);
    await waitDocs(1, W, 8000);
    if (Date.now() - pageStart > 24000) throw new Error('[photopea-place] 层太多，一次求值 30s 装不下（已放 ' + (i + 1) + ' 层）');
  }
  const { bin, got } = await pp('app.activeDocument = app.documents[' + B + ']; app.activeDocument.saveToOE(' + JSON.stringify(format) + ');', 20000);
  if (!bin) throw new Error('[photopea-place] saveToOE 没回二进制: ' + got.join('/'));

  const keepName = String(params.keep || '');
  if (keepName) await pp('app.activeDocument.name = ' + JSON.stringify(keepName) + '; var kd = app.activeDocument; ' + 'for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();' + ' app.activeDocument = kd;', 8000, '留下结果');
  else await pp('for (var i = app.documents.length - 1; i >= 0; i--) if (String(app.documents[i].name).indexOf("~stream~") === 0) app.documents[i].close();', 8000, '收尾');
  const u8 = new Uint8Array(bin); let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
  return { items: [{ guid: 'scene-' + Date.now(), format, width: String(W), height: String(H), layers: String(layers.length), bytes: String(u8.length), data: btoa(s) }], cursor: '' };
}
